import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('getisord_2023_energy.csv')
adjacency = pd.read_csv('borough_adjacency.csv')

# Define the neighborhood structure
neighborhoods = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Calculate the combined Energy values
combined_values = {}
for index, row in data.iterrows():
    if row['borough'] not in neighborhoods:
        combined_values[row['borough']] = row['Energy_value']
    else:
        combined_values[row['borough']] = row['Energy_value'] + sum(data[data['borough'].isin(neighborhoods[row['borough']])]['Energy_value'])

# Compute the Getis-Ord Gi* statistic
gi_values = {}
for borough, value in combined_values.items():
    neighbors = neighborhoods[borough]
    if len(neighbors) == 0:
        gi_values[borough] = value
    else:
        mean_value = data['Energy_value'].mean()
        std_dev = data['Energy_value'].std()
        gi_values[borough] = (value - mean_value) / (std_dev * np.sqrt(len(neighbors)))

# Calculate z-scores
z_scores = {}
for borough, value in gi_values.items():
    if value != 0:
        z_scores[borough] = np.abs(value)

# Identify statistically significant hot and cold spots
significant_boroughs = {}
for borough, value in z_scores.items():
    if value > 1.96:
        significant_boroughs[borough] = (f"HOT, Gi*={value}, gi_value={value}")
    elif value < -1.96:
        significant_boroughs[borough] = (f"COLD, Gi*={value}, gi_value={value}")

# Print the results
data_points_used = len(data) - data['Energy_value'].isnull().sum()
print(f"data_points_used = {data_points_used}")
if len(significant_boroughs) == 0:
    print("FINAL ANSWER: none")
else:
    print(f"FINAL ANSWER: {', '.join(significant_boroughs.values())}")

# Print the list of boroughs that are statistically significant hot or cold spots
print(f"FINAL ANSWER: {', '.join([f"{borough} ({result})" for borough, result in significant_boroughs.items()])}")

import pandas as pd
import numpy as np

# Load the data
data = pd.read_csv('getisord_2023_energy.csv')
adjacency = pd.read_csv('borough_adjacency.csv')

# Check for missing values and exclude rows with missing values
data_points_used = data['Energy_value'].count()

# Define the neighborhood structure
neighborhoods = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Calculate the combined Energy values
combined_values = {}
for borough in data['borough']:
    if borough not in neighborhoods:
        combined_values[borough] = data.loc[data['borough'] == borough, 'Energy_value'].values[0]
    else:
        combined_values[borough] = data.loc[data['borough'] == borough, 'Energy_value'].values[0] + sum(data.loc[data['borough'].isin(neighborhoods[borough]), 'Energy_value'])

# Compute the Getis-Ord Gi* statistic
gi_values = {}
for borough in combined_values:
    gi_values[borough] = (combined_values[borough] - data['Energy_value'].mean()) / data['Energy_value'].std()

# Calculate z-scores
z_scores = {}
for borough in gi_values:
    z_scores[borough] = np.abs(gi_values[borough]) / (1.96 * data['Energy_value'].std() / np.sqrt(len(data)))

# Identify statistically significant hot and cold spots
significant_boroughs = {}
for borough in z_scores:
    if z_scores[borough] > 1.96:
        significant_boroughs[borough] = 'HOT'
    elif z_scores[borough] < -1.96:
        significant_boroughs[borough] = 'COLD'

# Print the results
results = []
for borough in significant_boroughs:
    results.append(f"{borough} ({significant_boroughs[borough]}, Gi*={gi_values[borough]}, gi_value={gi_values[borough]})")

# Print the number of data points used
print(f"data_points_used = {data_points_used}")

# Print the final answer
if results:
    print(f"FINAL ANSWER: {', '.join(results)}")
else:
    print("FINAL ANSWER: none")
